    #[test]
    fn get_explorer_account_qr_parses_payload_and_omits_query_params() {
        let account_id = ALICE_ID.to_string();
        let address = AccountAddress::from_account_id(&ALICE_ID).expect("address from account");
        let i105_literal = address.to_i105().expect("i105 literal");
        let snapshots: SnapshotStore = Arc::new(Mutex::new(Vec::new()));
        let client = client_with_base_url(base_url());
        let payload = format!(
            r#"{{
  "canonical_id":"{account_id}",
  "literal":"{i105_literal}",
  "network_prefix":73,
  "error_correction":"M",
  "modules":192,
  "qr_version":5,
  "svg":"<svg i105 />"
}}"#
        );
        let response = json_response(StatusCode::OK, &payload);
        let snapshot_store = Arc::clone(&snapshots);
        let qr = with_mock_http(respond_with(&snapshot_store, response), || {
            client.get_explorer_account_qr(&account_id)
        })
        .expect("explorer QR request succeeds");
        assert_eq!(qr.canonical_id, account_id);
        assert_eq!(qr.literal, i105_literal);
        assert_eq!(qr.network_prefix, 73);
        assert_eq!(qr.modules, 192);
        assert_eq!(qr.qr_version, 5);
        assert_eq!(qr.error_correction, "M");
        let snapshot = snapshots
            .lock()
            .expect("snapshot lock")
            .first()
            .cloned()
            .expect("snapshot captured");
        let expected_url = join_torii_url(
            &client.torii_url,
            &format!("v1/explorer/accounts/{account_id}/qr"),
        );
        assert_eq!(snapshot.url.path(), expected_url.path());
        assert_eq!(snapshot.url.query(), None);
        assert!(
            snapshot.headers.iter().any(|(name, value)| {
                name.eq_ignore_ascii_case("accept") && value == APPLICATION_JSON
            }),
            "request should set Accept: application/json"
        );
    }

    #[test]
    fn txs_same_except_for_nonce_have_different_hashes() {
        let client = Client::new(Config {
            transaction_add_nonce: true,
            ..config_factory()
        });

        let build_transaction =
            || client.build_transaction(Vec::<InstructionBox>::new(), Metadata::default());
        let tx1 = build_transaction();
        let tx2 = build_transaction();
        assert_ne!(tx1.hash(), tx2.hash());

        let tx2 = {
            let mut tx = TransactionBuilder::new(client.chain.clone(), client.account.clone())
                .with_executable(tx1.instructions().clone())
                .with_metadata(tx1.metadata().clone());

            tx.set_creation_time(tx1.creation_time());
            if let Some(nonce) = tx1.nonce() {
                tx.set_nonce(nonce);
            }
            if let Some(transaction_ttl) = client.transaction_ttl {
                tx.set_ttl(transaction_ttl);
            }

            client.sign_transaction(tx)
        };
        assert_eq!(tx1.hash(), tx2.hash());
    }

    #[test]
    fn try_sign_transaction_attaches_verifiable_signature() {
        let client = client_with_base_url(base_url());
        let builder = TransactionBuilder::new(client.chain.clone(), client.account.clone())
            .with_instructions([Log::new(Level::INFO, "client checked signing".into())])
            .with_metadata(Metadata::default());

        let tx = client
            .try_sign_transaction(builder)
            .expect("client transaction signing should succeed");

        tx.verify_signature()
            .expect("client transaction signature must verify");
        assert_eq!(tx.authority(), &client.account);
    }

    #[test]
    fn submit_transaction_uses_norito_content_type_header_and_signed_transaction_payload() {
        let store: SnapshotStore = Arc::new(Mutex::new(Vec::new()));
        let capabilities_body = compatible_capabilities_body();
        let responder = {
            let store = Arc::clone(&store);
            move |snapshot: RequestSnapshot| {
                let path = snapshot.url.path().to_string();
                store.lock().expect("snapshot lock").push(snapshot);
                let response = if path == "/v1/node/capabilities" {
                    json_response(StatusCode::OK, &capabilities_body)
                } else {
                    HttpResponse::builder()
                        .status(StatusCode::OK)
                        .body(Vec::new())
                        .expect("response build")
                };
                Ok(response)
            }
        };

        with_mock_http(responder, || {
            let mut client = client_with_base_url(base_url());
            client
                .headers
                .insert("Content-Type".to_string(), "text/plain".to_string());
            let tx = client.build_transaction(Vec::<InstructionBox>::new(), Metadata::default());
            client
                .submit_transaction(&tx)
                .expect("transaction submission succeeds");
        });

        let store_guard = store.lock().expect("snapshot lock");
        assert_eq!(
            store_guard.len(),
            2,
            "expected node capabilities + transaction requests"
        );
        let capabilities_snapshot = store_guard
            .iter()
            .find(|snapshot| snapshot.url.path() == "/v1/node/capabilities")
            .expect("capabilities snapshot captured");
        assert_single_accept_header(capabilities_snapshot, APPLICATION_JSON);
        let snapshot = store_guard
            .iter()
            .find(|snapshot| snapshot.url.path() == torii_uri::TRANSACTION)
            .cloned()
            .expect("transaction snapshot captured");
        let content_type_headers: Vec<_> = snapshot
            .headers
            .iter()
            .filter(|(name, _)| name.eq_ignore_ascii_case("content-type"))
            .collect();
        assert_eq!(
            content_type_headers.len(),
            1,
            "expected a single Content-Type header: {:?}",
            snapshot.headers
        );
        assert_eq!(
            content_type_headers[0].1.as_str(),
            APPLICATION_NORITO,
            "transaction requests must advertise Norito payloads"
        );
        SignedTransaction::decode_all_versioned(&snapshot.body)
            .expect("transaction request body must be a versioned SignedTransaction");
        assert!(
            TransactionEntrypoint::decode_all_versioned(&snapshot.body).is_err(),
            "public /transaction requests must not use internal TransactionEntrypoint envelopes"
        );
    }

